package glitch

import data.glitch_lib

# List of weak algorithms, protocols, and hashing methods based on CWE-326
weak_algorithms := {"DES", "3DES", "TripleDES", "DESede", "RC4", "ARC4", "ARCFOUR", "Blowfish", "RC2", "IDEA", "Plaintext", "MD5", "SHA-1", "SHA-224", "HMAC-MD5", "HMAC-SHA1", "SSLv2", "SSLv3", "TLS 1.0", "TLS 1.1", "XOR", "Base64", "Custom", "Proprietary", "OTP", "md5_crypt", "sha1"}

# List of weak key sizes (as strings for comparison)
weak_key_sizes := {"512", "64", "128", "1024"}

# List of weak elliptic curves
weak_curves := {"secp192k1", "sect163k1"}

# Helper to check if a value contains a weak cryptographic primitive
contains_weak_crypto(str_val) {
    lower_val := lower(str_val)
    # Check if the value directly matches a weak algorithm or contains a weak pattern
    regex.match(sprintf("(?i)\\b(%s)\\b", [concat("|", weak_algorithms)]), lower_val)
} else {
    lower_val := lower(str_val)
    contains(lower_val, "aes-128")
} else {
    lower_val := lower(str_val)
    contains(lower_val, weak_curves[_])
} else {
    # Regex match for key size patterns in strings (e.g., key_size = 1024)
    regex.match("key_size\\s*[:=]\\s*(512|64|128|1024)", lower(str_val))
}

# Helper to check if a value represents a weak key size
is_weak_key_size(val) {
    val.ir_type == "Integer"
    size := sprintf("%d", [val.value])
    size == weak_key_sizes[_]
} else {
    val.ir_type == "String"
    size := lower(val.value)
    size == weak_key_sizes[_]
}

# Rule to detect weak cryptographic algorithms/protocols in attributes (Ansible, Puppet)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Focus on attributes that configure cryptographic settings
    lower_name := lower(attr.name)
    algorithm_attrs := {"algorithm", "cipher", "encryption_algorithm", "encryption_standard", "storage_encryption", "hash_algorithm", "digest", "signature_algorithm", "password_hash", "stored_key", "encryption_type", "custom_encryption", "encoding", "ssl_policy", "tls_version", "protocol", "min_tls_version", "enforce_tls", "encrypt", "cipher_suites"}
    algorithm_attrs[_] == lower_name

    # Check value for weak primitives
    is_weak_value(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of weak or outdated cryptographic algorithm or protocol. (CWE-326)"
    }
}

# Rule to detect weak cryptographic algorithms/protocols in variables (Chef)
Glitch_Analysis[result] {
